mapper.update:
update merchant_operator
set role_code = #{roleCode}, version = version + 1,
    update_by = #{updateBy}, update_time = now()
where id = #{id} and merchant_id = #{merchantId}
  and status = 'ACTIVE' and version = #{expectedVersion}

update merchant_operator
set status = 'REVOKED', revoked_by_member_id = #{revokedByMemberId},
    revoked_at = now(), revoke_reason = #{revokeReason}, version = version + 1,
    update_by = #{updateBy}, update_time = now()
where id = #{id} and merchant_id = #{merchantId}
  and status = 'ACTIVE' and version = #{expectedVersion}
